from pathlib import Path
import base64,hashlib,json,subprocess,re,sys
r=Path('/home/cat/projects/RK3576/rk3576_multimodal_stage5_review');p=r/'tools/stage5_05_voice_run.py';old=p.read_bytes();assert hashlib.sha256(old).hexdigest()=='d04e7018ce4f165fa48bc70fd3f0102971a90a2b08068bcc739a0ff09033e68e'
with (r/'reports/stage5_05_board/voice_run_before_desktop_identity.py').open('xb') as f:f.write(old)
p.write_bytes(base64.b64decode(''));sys.path.insert(0,str(r/'tools'))
from stage5_05_voice_run import owner_identity,devices,discover_audio
baseline={'primary_nodes':{},'scope':'currently observed root seat/display DRM holders only; no SDK process launched; exact PID+start token+UID+comm+cmdline'}
for node in ['/dev/dri/card1']:
 q=subprocess.run(['sudo','-n','--','/usr/bin/fuser','-v',node],capture_output=True,text=True,timeout=15);assert q.returncode in (0,1)
 identities=[owner_identity(int(x)) for x in q.stdout.split() if x.isdigit()]
 assert identities and {x['comm'] for x in identities}=={'systemd','systemd-logind','Xorg'} and all(x['uid']==0 for x in identities)
 for x in identities:assert Path(x['cmdline'].split()[0]).name in {'init','systemd','systemd-logind','Xorg'},x
 baseline['primary_nodes'][node]={'command':q.args,'stdout':q.stdout,'stderr':q.stderr,'returncode':q.returncode,'identities':identities}
with (r/'reports/stage5_05_board/npu_primary_baseline.json').open('x') as f:json.dump(baseline,f,indent=2)
state=devices(discover_audio());assert state['clear'],state
print('EXACT_DESKTOP_BASELINE',json.dumps(baseline));print('DEVICE_CLEAR_WITH_FROZEN_DESKTOP_OWNERS',state['clear'])
