with (b/'final_burst_audio/result.json').open('x') as f:json.dump({'returncode':None,'runner_returncode':1,'program_started':False,'stage':'preflight','input_mode':'NOT_EXECUTED: protection refused existing root DRM seat owners'},f,indent=2)
with (b/'final_matrix/result.json').open('x') as f:json.dump({'complete':False,'stopped_at':'final_burst_audio preflight','failure_reason':'NPU primary desktop owners require exact baseline classification','completed_cases':json.loads((b/'final_matrix/progress.json').read_text())},f,indent=2)
